    /**
     * The paused run as JSON (requests and snapshot, not the answers), to store
     * and read back with [`PausedRun::from_json`]. It holds the run's variables
     * (never secrets): keep it in the app's private storage.
     */
    func toJson()  -> String
    
    /**
